insert into public.exam_questions (subject, question, options, answer) values ('정치', '전 세계에 흩어져 있는 교회이며, 삼위일체 하나님을 믿는 그리스도인들이 속한 교회의 유형은?', '["가정 교회", "지하 교회", "무형 교회", "유형 교회"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('정치', '''유형 교회''의 특징으로 옳은 것은?', '["건물이 없는 영적인 공동체만을 의미한다.", "특정 교단에 소속되지 않는다.", "전 세계에 흩어져 있는 그리스도인들의 구체적인 공동체를 포함한다.", "인간의 눈으로 직접 확인할 수 없다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('정치', '''무형 교회''의 본질적인 의미는 무엇입니까?', '["육안으로 볼 수 없는 건물을 가진 교회", "비밀리에 운영되는 지하 교회", "조직이나 제도가 없는 자유로운 공동체", "모든 신자들이 영적으로 하나님과 연결된 총체적 공동체"]'::jsonb, 3);
